+  .footer-grid{ grid-template-columns: 1fr; }
+  .footer-col{ border: 1px solid rgba(50,70,47,.12); border-radius: 16px; background: rgba(255,255,255,.75); }
+  .footer-col button{
+    width: 100%;
+    background: transparent;
+    border: 0;
+    padding: 12px 12px;
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    gap: 10px;
+    cursor: pointer;
+  }
+  .footer-col button:focus-visible{ outline: 3px solid rgba(0,130,74,.35); outline-offset: 2px; border-radius: 16px; }
+  .footer-col h3{ margin: 0; }
+  .footer-col .footer-links{ display: none; padding: 0 12px 12px; }
+  .footer-col[data-open="true"] .footer-links{ display: grid; }
+  .footer-col a{ padding: 8px 0; }
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{ scroll-behavior: auto !important; transition: none !important; animation: none !important; }
+}
+
*** End Patch
PATCH"}

